  select jsonb_build_object('definition',pg_get_functiondef(p.oid),'prosrc',p.prosrc,'identity',pg_get_function_identity_arguments(p.oid),'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'config',p.proconfig,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,'parallel',p.proparallel,'kind',p.prokind,'language',l.lanname) into actual_n from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(spec.key);
  if actual_n is distinct from spec.value then raise exception 'RETAINED_EXPORT_BEFORE_METADATA_MISMATCH %',spec.key;end if;
 end loop;
